import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.StringTokenizer;

public class C
{
	static PrintWriter out = new PrintWriter(
			new BufferedOutputStream(System.out));
	static MyScanner sc = new MyScanner(System.in);

	public static void main(String... args)
	{
		int a = sc.nextInt();
		int b = sc.nextInt();
		int l = sc.nextInt() - 1;
		int r = sc.nextInt();
		int mod = a + b;
		int delta = l / mod * mod;
		l -= delta;
		r -= delta;

		if (r > mod * 3)
		{
			r = r % mod + mod * 3;
		}

		int[] seq = new int[r];

		for (int i = 0; i < r; i++)
		{
			seq[i] = i;
		}

		Generator gen = new Generator(seq, a, b);
		gen.build(a);
		int first = gen.unique(l, r);

		for (int i = a; i < a + b && i < r && b < r; i++)
		{
			seq[i] = seq[b];
		}

		gen.build(a + b);
		int second = gen.unique(l, r);

		out.println(Math.min(first, second));
		out.flush();
	}

	private static class Generator
	{
		int[] seq;
		int a;
		int b;
		int m;

		Generator(int[] seq, int a, int b)
		{
			this.seq = seq;
			this.a = a;
			this.b = b;
			this.m = a + b;
		}

		void build(int start)
		{
			int i = start;
			while (i < seq.length)
			{
				if (i % m < a)
				{
					HashSet<Integer> used = new HashSet<Integer>();
					for (int j = i - 1; i - j <= a; j--)
					{
						used.add(seq[j]);
					}

					for (int j = 0; i % m != a && i < seq.length; i++, j++)
					{
						while (used.contains(j))
						{
							j++;
						}
						used.add(j);
						seq[i] = j;
					}
				}
				else
				{
					seq[i] = seq[i - 1];
					i++;
				}
			}
		}

		int unique(int l, int r)
		{
			HashSet<Integer> set = new HashSet<Integer>();
			for (int i = l; i < r; i++)
			{
				set.add(seq[i]);
			}
			return set.size();
		}
	}

	private static class MyScanner
	{
		BufferedReader br;
		StringTokenizer st;

		MyScanner(InputStream in)
		{
			this.br = new BufferedReader(new InputStreamReader(in));
		}

		String next()
		{
			while (this.st == null || !this.st.hasMoreElements())
			{
				try
				{
					this.st = new StringTokenizer(this.br.readLine());
				}
				catch (IOException e)
				{
					e.printStackTrace();
				}
			}
			return this.st.nextToken();
		}

		int nextInt()
		{
			return Integer.parseInt(this.next());
		}

		long nextLong()
		{
			return Long.parseLong(this.next());
		}

		double nextDouble()
		{
			return Double.parseDouble(this.next());
		}

		String nextLine()
		{
			if (this.st == null || !this.st.hasMoreElements())
			{
				String str = "";
				try
				{
					str = this.br.readLine();
				}
				catch (IOException e)
				{
					e.printStackTrace();
				}
				return str;
			}
			else
			{
				StringBuilder str = new StringBuilder();
				while (this.st.hasMoreElements())
				{
					str.append(this.st.nextToken());
					str.append(" ");
				}
				str.deleteCharAt(str.length() - 1);
				return str.toString();
			}
		}

	}
}
